#!/usr/bin/env bash
# The agent definitions of all three tools come from one place. .agents/agents/<name>.md holds each agent's description,
# tier and instructions; .agents/agents/tiers.json holds the model of each tier per tool (Claude Code, Copilot, Codex).
# The definitions the tools read are generated from them: .claude/agents/<name>.md (model: sonnet|opus|haiku),
# .github/agents/<name>.agent.md (Copilot's model names) and .codex/agents/<name>.toml (model and reasoning effort).
# Never edit the generated files: change .agents/agents and run sync. check also fails when a definition has no tier or
# the model of a tool is missing, so the three tools can't drift apart.
#
#   agents.sh sync    write the definitions of all three tools from .agents/agents
#   agents.sh check   fail if a definition lacks its tier or a tool's model, or a generated file differs from its origin
set -euo pipefail
source "$(dirname "${BASH_SOURCE[0]}")/_lib.sh"

usage() { usage_of "$0"; }

SRC="$ROOT/.agents/agents"
TIERS="$SRC/tiers.json"
CODEX_CONFIG="$ROOT/.codex/config.toml"
# The agents every tool must have, and the tier each one runs on (docs/agents/build.md).
AGENTS="builder reviewer mechanic"
tier_of() {
  case "$1" in
    builder) echo mid ;;
    reviewer) echo high ;;
    mechanic) echo small ;;
  esac
}

# Where each tool reads the definition of agent $1, relative to the repo root.
targets() { printf '%s\n' ".claude/agents/$1.md" ".github/agents/$1.agent.md" ".codex/agents/$1.toml"; }
target_dirs() { printf '%s\n' ".claude/agents" ".github/agents" ".codex/agents"; }
target_ext() {
  case "$1" in
    .claude/agents) echo .md ;;
    .github/agents) echo .agent.md ;;
    .codex/agents) echo .toml ;;
  esac
}

# Frontmatter value of $2 in the source file $1.
field() {
  awk -v key="$2" '
    NR == 1 { if ($0 != "---") exit; next }
    $0 == "---" { exit }
    index($0, key ": ") == 1 { print substr($0, length(key) + 3); exit }
  ' "$1"
}

# What follows the frontmatter of the source file $1.
body() { awk 'seen >= 2 { print; next } $0 == "---" { seen++; next }' "$1" | sed '1{/^$/d;}'; }

tier_value() { jq -r --arg t "$1" "(.[\$t] // {}) | $2 // empty" "$TIERS"; }
quote() { jq -Rn --arg v "$1" '$v'; }

header() { echo "Generated by scripts/agents.sh from .agents/agents/$1.md. Don't edit it by hand."; }

render_claude() {
  local name="$1" file="$SRC/$1.md" tier
  tier="$(field "$file" tier)"
  printf -- '---\n# %s\nname: %s\ndescription: %s\nmodel: %s\n---\n\n' \
    "$(header "$name")" "$name" "$(quote "$(field "$file" description)")" "$(tier_value "$tier" .claude)"
  body "$file"
}

render_copilot() {
  local name="$1" file="$SRC/$1.md" tier models
  tier="$(field "$file" tier)"
  models="$(jq -r --arg t "$tier" '.[$t].copilot | map("'"'"'" + . + "'"'"'") | join(", ")' "$TIERS")"
  printf -- '---\n# %s\nname: %s\ndescription: %s\nmodel: [%s]\n---\n\n' \
    "$(header "$name")" "$name" "$(quote "$(field "$file" description)")" "$models"
  body "$file"
}

render_codex() {
  local name="$1" file="$SRC/$1.md" tier
  tier="$(field "$file" tier)"
  printf '# %s\nname = "%s"\ndescription = %s\nmodel = "%s"\nmodel_reasoning_effort = "%s"\ndeveloper_instructions = %s\n' \
    "$(header "$name")" "$name" "$(quote "$(field "$file" description)")" \
    "$(tier_value "$tier" .codex.model)" "$(tier_value "$tier" .codex.effort)" "'''"
  body "$file"
  echo "'''"
}

render() {
  case "$2" in
    .claude/*) render_claude "$1" ;;
    .github/*) render_copilot "$1" ;;
    .codex/*) render_codex "$1" ;;
  esac
}

# Problems with the sources and the tier table, one per line; nothing when they are fine.
problems() {
  local name file tier tool want
  if [ ! -f "$TIERS" ] || ! jq -e . "$TIERS" >/dev/null 2>&1; then
    echo ".agents/agents/tiers.json: missing or not JSON"
    return
  fi
  for tier in high mid small; do
    [ "$(tier_value "$tier" .claude)" ] || echo "tiers.json: $tier: no claude model"
    [ "$(tier_value "$tier" '.copilot[0]')" ] || echo "tiers.json: $tier: no copilot model"
    [ "$(tier_value "$tier" .codex.model)" ] || echo "tiers.json: $tier: no codex model"
    [ "$(tier_value "$tier" .codex.effort)" ] || echo "tiers.json: $tier: no codex effort"
  done
  for name in $AGENTS; do
    file="$SRC/$name.md"
    [ -f "$file" ] || { echo ".agents/agents/$name.md: missing"; continue; }
    [ "$(field "$file" name)" = "$name" ] || echo ".agents/agents/$name.md: name must be $name"
    [ -n "$(field "$file" description)" ] || echo ".agents/agents/$name.md: no description"
    [ -n "$(body "$file")" ] || echo ".agents/agents/$name.md: no instructions"
    ! body "$file" | grep -q "'''" || echo ".agents/agents/$name.md: instructions contain ''' (breaks the Codex definition)"
    tier="$(field "$file" tier)"
    want="$(tier_of "$name")"
    if [ -z "$tier" ]; then
      echo ".agents/agents/$name.md: no tier"
    elif [ -z "$(tier_value "$tier" '.claude // .codex')" ]; then
      echo ".agents/agents/$name.md: unknown tier $tier"
    elif [ "$tier" != "$want" ]; then
      echo ".agents/agents/$name.md: tier is $tier, it must be $want"
    fi
  done
  for file in "$SRC"/*.md; do
    [ -e "$file" ] || continue
    name="$(basename "$file" .md)"
    case " $AGENTS " in *" $name "*) ;; *) echo ".agents/agents/$name.md: not one of: $AGENTS" ;; esac
  done
  tool="$(sed -nE 's/^model = "([^"]*)".*/\1/p' "$CODEX_CONFIG" 2>/dev/null | head -1)"
  want="$(tier_value high .codex.model)"
  [ "$tool" = "$want" ] || echo ".codex/config.toml: model is ${tool:-unset}, the high tier is $want"
  tool="$(sed -nE 's/^review_model = "([^"]*)".*/\1/p' "$CODEX_CONFIG" 2>/dev/null | head -1)"
  [ "$tool" = "$want" ] || echo ".codex/config.toml: review_model is ${tool:-unset}, the high tier is $want"
}

# Generated files with no source agent.
stale() {
  local dir ext file name
  for dir in $(target_dirs); do
    ext="$(target_ext "$dir")"
    for file in "$ROOT/$dir"/*; do
      [ -e "$file" ] || continue
      name="$(basename "$file" "$ext")"
      case " $AGENTS " in *" $name "*) ;; *) echo "$dir/$(basename "$file"): no source in .agents/agents" ;; esac
    done
  done
}

# Generated files that are missing or differ from what their source renders.
drift() {
  local name path
  for name in $AGENTS; do
    for path in $(targets "$name"); do
      if [ ! -f "$ROOT/$path" ]; then
        echo "$path: missing"
      elif ! render "$name" "$path" | cmp -s - "$ROOT/$path"; then
        echo "$path: differs from .agents/agents/$name.md and tiers.json"
      fi
    done
  done
}

cmd_check() {
  local issues
  issues="$(problems)"
  [ -n "$issues" ] || issues="$(drift)"
  issues="$(printf '%s\n%s\n' "$issues" "$(stale)" | sed '/^$/d')"
  [ -z "$issues" ] || die "agent definitions are not in order:
$issues
Fix the source in .agents/agents and run scripts/agents.sh sync."
  echo "✅ agent definitions match .agents/agents (${AGENTS// /, })"
}

cmd_sync() {
  local issues name path dir ext file
  issues="$(problems)"
  [ -z "$issues" ] || die "agent sources are not in order:
$issues"
  for name in $AGENTS; do
    for path in $(targets "$name"); do
      mkdir -p "$ROOT/$(dirname "$path")"
      render "$name" "$path" > "$ROOT/$path"
    done
  done
  for dir in $(target_dirs); do
    ext="$(target_ext "$dir")"
    for file in "$ROOT/$dir"/*; do
      [ -e "$file" ] || continue
      case " $AGENTS " in *" $(basename "$file" "$ext") "*) ;; *) rm -f "$file"; echo "🗑  removed $dir/$(basename "$file")" ;; esac
    done
  done
  echo "✅ agent definitions written for ${AGENTS// /, }"
}

case "${1:-}" in
  sync)  need_cmd jq; cmd_sync ;;
  check) need_cmd jq; cmd_check ;;
  *)     usage ;;
esac
